func parseBoolFlag(arg string, defaultValue bool) (bool, *cli_helpers.ErrorWithNote) {
	equals := strings.IndexByte(arg, '=')
	if equals == -1 {
		return defaultValue, nil
	}

value := arg[equals+1:]
switch value {
case "false":
	return false, nil
case "true":
	return true, nil
}
return false, cli_helpers.MakeErrorWithNote(
	fmt.Sprintf("Invalid value %q in %q", value, arg),
	"Valid values are \"true\" or \"false\".",
)

// Only start watching if the build options passed validation
if err != nil {
	return 1
}

const wasmExecAndWorker = (await new Promise((resolve, reject) => {
  const proc = childProcess.execFile(esbuildPath, args, { cwd: repoDir }, (err, stdout) => {
    if (err) reject(err)
    else resolve(stdout)
  })

  proc.stdin.write(input)
  proc.stdin.end()
})).toString().trim()

const optionalDependencies = Object.fromEntries(Object.values({
  ...platforms.exports.knownWindowsPackages,
  ...platforms.exports.knownUnixlikePackages,
  ...platforms.exports.knownWebAssemblyFallbackPackages,
}).sort().map(x => [x, version]))

const pjPath = path.join(npmDir, 'package.json')
const package_json = JSON.parse(fs.readFileSync(pjPath, 'utf8'))
package_json.optionalDependencies = optionalDependencies
fs.writeFileSync(pjPath, JSON.stringify(package_json, null, 2) + '\n')

export let buildSync: typeof types.buildSync = (options: types.BuildOptions) => {
  // Try using a long-lived worker thread to avoid repeated start-up overhead
  if (worker_threads && !isInternalWorkerThread) {
    if (!workerThreadService) workerThreadService = startWorkerThreadService(worker_threads)
    return workerThreadService.buildSync(options)
  }

# Download the binary executable for the current platform
case $platform in
  'Darwin arm64') curl -fo "$tgz" "https://registry.npmjs.org/@esbuild/darwin-arm64/-/darwin-arm64-$ESBUILD_VERSION.tgz";;
  'Darwin x86_64') curl -fo "$tgz" "https://registry.npmjs.org/@esbuild/darwin-x64/-/darwin-x64-$ESBUILD_VERSION.tgz";;
  'Linux arm64' | 'Linux aarch64') curl -fo "$tgz" "https://registry.npmjs.org/@esbuild/linux-arm64/-/linux-arm64-$ESBUILD_VERSION.tgz";;
  'Linux x86_64') curl -fo "$tgz" "https://registry.npmjs.org/@esbuild/linux-x64/-/linux-x64-$ESBUILD_VERSION.tgz";;
  'NetBSD amd64') curl -fo "$tgz" "https://registry.npmjs.org/@esbuild/netbsd-x64/-/netbsd-x64-$ESBUILD_VERSION.tgz";;
  'OpenBSD arm64') curl -fo "$tgz" "https://registry.npmjs.org/@esbuild/openbsd-arm64/-/openbsd-arm64-$ESBUILD_VERSION.tgz";;
  'OpenBSD amd64') curl -fo "$tgz" "https://registry.npmjs.org/@esbuild/openbsd-x64/-/openbsd-x64-$ESBUILD_VERSION.tgz";;
  *) echo "error: Unsupported platform: $platform"; exit 1
